#!/usr/bin/env python3
"""按用户确认的对应关系修正布局配色（1=CapCut 亮、2=Blurrr 深、3=AM 深蓝、4=快影 深）。

之前把快影 / AM 当成亮色界面，用户指出它们其实是**深色编辑器**：
  CapCut  白底 #FFFFFF / 面 #FAFBFF / 文字 #090C14 / 主色 #00CAE0（青）
  Blurrr  深底 #0E1014 / 面 #15181E / 文字 #F2F4F8 / 主色 #03DAC6（青绿）
  AM      深蓝 #1B1E2F / 面 #1F2238 / 文字 #EDEFF7 / 主色 #F16586（粉）
  快影     深底 #121212 / 面 #1C1C1E / 文字 #F2F2F2 / 主色 #FF5000（橙红）

全部写进 tokens，不读用户主题色；ae 仍然回到用户自己的主题。
"""
from __future__ import annotations

import os
from pathlib import Path

MARKER = "EFFECTCRAFT_OURS_BRAND_PALETTE_V2"

OLD = '        // EFFECTCRAFT_OURS_BRAND_PALETTE_V1 — 每套布局用**拆包得到的真实配色**，不再从我们自己的主题派生。\n        // 颜色取自各家 APK 的 resources.arsc（见 HANDOFF「品牌配色来源」）：\n        //   CapCut   白底 #FFFFFF / 近白面 #FAFBFF / 文字 #090C14 / 强调 #00CAE0（青）\n        //   快影      白底 #FFFFFF / 文字 #222222 / 次要 #666666 / 分隔 #E6E6E6 / 强调 #FF5000（橙）\n        //   AM       白底 #FFFFFF / 面 #F7F8FC / 文字 #1F2238 / 强调 #F16586（粉）\n        //   Blurrr   深底 #121214 / 面 #17171A / 文字 #F2F2F5 / 强调 #03DAC6（青绿）\n        {\n            let ws = self.ui.workspace.as_str().to_string();\n            let c = egui::Color32::from_rgb;\n            let pal: Option<(bool, [egui::Color32; 8])> = match ws.as_str() {\n                "capcut" => Some((\n                    true,\n                    [\n                        c(0xFF, 0xFF, 0xFF), // app_bg\n                        c(0xFA, 0xFB, 0xFF), // panel_bg\n                        c(0x09, 0x0C, 0x14), // text\n                        c(0x6B, 0x70, 0x79), // text_dim\n                        c(0xE7, 0xE9, 0xEF), // separator\n                        c(0x00, 0xCA, 0xE0), // accent\n                        c(0xF3, 0xF5, 0xF9), // field_bg\n                        c(0xF6, 0xF7, 0xFE), // row_alt\n                    ],\n                )),\n                "kuaishou" => Some((\n                    true,\n                    [\n                        c(0xFF, 0xFF, 0xFF),\n                        c(0xFF, 0xFF, 0xFF),\n                        c(0x22, 0x22, 0x22),\n                        c(0x66, 0x66, 0x66),\n                        c(0xE6, 0xE6, 0xE6),\n                        c(0xFF, 0x50, 0x00),\n                        c(0xF5, 0xF5, 0xF5),\n                        c(0xFA, 0xFA, 0xFA),\n                    ],\n                )),\n                "am" | "jianying" => Some((\n                    true,\n                    [\n                        c(0xFF, 0xFF, 0xFF),\n                        c(0xF7, 0xF8, 0xFC),\n                        c(0x1F, 0x22, 0x38),\n                        c(0x6B, 0x6E, 0x85),\n                        c(0xE3, 0xE4, 0xEC),\n                        c(0xF1, 0x65, 0x86),\n                        c(0xF5, 0xF6, 0xFA),\n                        c(0xF2, 0xF3, 0xF9),\n                    ],\n                )),\n                "blurrr" => Some((\n                    false,\n                    [\n                        c(0x12, 0x12, 0x14),\n                        c(0x17, 0x17, 0x1A),\n                        c(0xF2, 0xF2, 0xF5),\n                        c(0x9A, 0x9A, 0xA2),\n                        c(0x2A, 0x2A, 0x30),\n                        c(0x03, 0xDA, 0xC6),\n                        c(0x1E, 0x1E, 0x22),\n                        c(0x1A, 0x1A, 0x1D),\n                    ],\n                )),\n                _ => None,\n            };\n            // 品牌色用于判断"当前 tokens 是否已经被某套布局改过"\n            let brand_accents = [\n                c(0x00, 0xCA, 0xE0),\n                c(0xFF, 0x50, 0x00),\n                c(0xF1, 0x65, 0x86),\n                c(0x03, 0xDA, 0xC6),\n            ];\n            let branded = brand_accents.contains(&self.tokens.accent);\n            let wants = match pal {\n                Some((light, [bg, panel, text, dim, sep, accent, field, alt])) => {\n                    let kind_ok = self.tokens.kind.is_light() == light;\n                    let same = kind_ok\n                        && self.tokens.app_bg == bg\n                        && self.tokens.panel_bg == panel\n                        && self.tokens.text == text\n                        && self.tokens.accent == accent\n                        && self.tokens.separator == sep\n                        && self.tokens.field_bg == field\n                        && self.tokens.row_alt == alt\n                        && self.tokens.text_dim == dim;\n                    if same {\n                        None\n                    } else {\n                        Some((light, [bg, panel, text, dim, sep, accent, field, alt]))\n                    }\n                }\n                None => {\n                    if branded\n                        || self.tokens.kind.is_light() != self.ui.theme.is_light()\n                        || self.tokens.app_bg != Tokens::from_prefs(&self.session.prefs, self.ui.theme).app_bg\n                    {\n                        Some((self.ui.theme.is_light(), [egui::Color32::TRANSPARENT; 8]))\n                    } else {\n                        None\n                    }\n                }\n            };\n            if let Some((light, [bg, panel, text, dim, sep, accent, field, alt])) = wants {\n                let kind = if light {\n                    crate::theme::ThemeKind::Light\n                } else {\n                    crate::theme::ThemeKind::Dark\n                };\n                let mut t = Tokens::from_prefs(&self.session.prefs, kind);\n                if accent != egui::Color32::TRANSPARENT {\n                    t.app_bg = bg;\n                    t.panel_bg = panel;\n                    t.header_bg = panel;\n                    t.text = text;\n                    t.text_dim = dim;\n                    t.text_faint = dim.gamma_multiply(0.75);\n                    t.separator = sep;\n                    t.field_bg = field;\n                    t.field_border = sep;\n                    t.row = bg;\n                    t.row_alt = alt;\n                    t.row_selected = accent.gamma_multiply(0.18);\n                    t.tl_bg = bg;\n                    t.tl_ruler_bg = panel;\n                    t.switch_well = field;\n                    t.accent = accent;\n                    t.focus = accent;\n                    t.accent_hover = accent.lerp_to_gamma(egui::Color32::WHITE, 0.22);\n                    t.cti = accent;\n                    t.timecode = accent;\n                    t.hot_text = accent;\n                    t.keyframe_selected = accent;\n                }\n                self.tokens = t;\n                crate::theme::apply_visuals(&ctx, &self.tokens);\n                ctx.set_theme(crate::theme::theme_preference(\n                    &self.session.prefs.appearance.appearance_mode,\n                    self.tokens.kind.is_light(),\n                ));\n            }\n        }'

NEW = '        // EFFECTCRAFT_OURS_BRAND_PALETTE_V2 — 每套布局用**拆包得到的真实配色**，不再从我们自己的主题派生。\n        // 颜色取自各家 APK 的 resources.arsc（见 HANDOFF「品牌配色来源」）：\n        //   CapCut   白底 #FFFFFF / 近白面 #FAFBFF / 文字 #090C14 / 强调 #00CAE0（青）\n        //   快影      白底 #FFFFFF / 文字 #222222 / 次要 #666666 / 分隔 #E6E6E6 / 强调 #FF5000（橙）\n        //   AM       白底 #FFFFFF / 面 #F7F8FC / 文字 #1F2238 / 强调 #F16586（粉）\n        //   Blurrr   深底 #121214 / 面 #17171A / 文字 #F2F2F5 / 强调 #03DAC6（青绿）\n        {\n            let ws = self.ui.workspace.as_str().to_string();\n            let c = egui::Color32::from_rgb;\n            let pal: Option<(bool, [egui::Color32; 8])> = match ws.as_str() {\n                "capcut" => Some((\n                    true,\n                    [\n                        c(0xFF, 0xFF, 0xFF), // app_bg\n                        c(0xFA, 0xFB, 0xFF), // panel_bg\n                        c(0x09, 0x0C, 0x14), // text\n                        c(0x6B, 0x70, 0x79), // text_dim\n                        c(0xE7, 0xE9, 0xEF), // separator\n                        c(0x00, 0xCA, 0xE0), // accent\n                        c(0xF3, 0xF5, 0xF9), // field_bg\n                        c(0xF6, 0xF7, 0xFE), // row_alt\n                    ],\n                )),\n                // 快影（图 4）：深色编辑器，主色橙红 #FF5000\n                "kuaishou" => Some((\n                    false,\n                    [\n                        c(0x12, 0x12, 0x12),\n                        c(0x1C, 0x1C, 0x1E),\n                        c(0xF2, 0xF2, 0xF2),\n                        c(0x9C, 0x9C, 0x9C),\n                        c(0x2B, 0x2B, 0x2F),\n                        c(0xFF, 0x50, 0x00),\n                        c(0x22, 0x22, 0x24),\n                        c(0x1A, 0x1A, 0x1C),\n                    ],\n                )),\n                // AM / Alight Motion（图 3）：深蓝紫面板 #1F2238，主色粉 #F16586\n                "am" | "jianying" => Some((\n                    false,\n                    [\n                        c(0x1B, 0x1E, 0x2F),\n                        c(0x1F, 0x22, 0x38),\n                        c(0xED, 0xEF, 0xF7),\n                        c(0x9A, 0xA0, 0xC0),\n                        c(0x2A, 0x2E, 0x45),\n                        c(0xF1, 0x65, 0x86),\n                        c(0x26, 0x2A, 0x45),\n                        c(0x23, 0x26, 0x3A),\n                    ],\n                )),\n                // Blurrr（图 2）：深色，辅色青 #03DAC6\n                "blurrr" => Some((\n                    false,\n                    [\n                        c(0x0E, 0x10, 0x14),\n                        c(0x15, 0x18, 0x1E),\n                        c(0xF2, 0xF4, 0xF8),\n                        c(0x9A, 0xA0, 0xAC),\n                        c(0x26, 0x2A, 0x32),\n                        c(0x03, 0xDA, 0xC6),\n                        c(0x1C, 0x20, 0x27),\n                        c(0x18, 0x1B, 0x21),\n                    ],\n                )),\n                _ => None,\n            };\n            // 品牌色用于判断"当前 tokens 是否已经被某套布局改过"\n            let brand_accents = [\n                c(0x00, 0xCA, 0xE0),\n                c(0xFF, 0x50, 0x00),\n                c(0xF1, 0x65, 0x86),\n                c(0x03, 0xDA, 0xC6),\n            ];\n            let branded = brand_accents.contains(&self.tokens.accent);\n            let wants = match pal {\n                Some((light, [bg, panel, text, dim, sep, accent, field, alt])) => {\n                    let kind_ok = self.tokens.kind.is_light() == light;\n                    let same = kind_ok\n                        && self.tokens.app_bg == bg\n                        && self.tokens.panel_bg == panel\n                        && self.tokens.text == text\n                        && self.tokens.accent == accent\n                        && self.tokens.separator == sep\n                        && self.tokens.field_bg == field\n                        && self.tokens.row_alt == alt\n                        && self.tokens.text_dim == dim;\n                    if same {\n                        None\n                    } else {\n                        Some((light, [bg, panel, text, dim, sep, accent, field, alt]))\n                    }\n                }\n                None => {\n                    if branded\n                        || self.tokens.kind.is_light() != self.ui.theme.is_light()\n                        || self.tokens.app_bg != Tokens::from_prefs(&self.session.prefs, self.ui.theme).app_bg\n                    {\n                        Some((self.ui.theme.is_light(), [egui::Color32::TRANSPARENT; 8]))\n                    } else {\n                        None\n                    }\n                }\n            };\n            if let Some((light, [bg, panel, text, dim, sep, accent, field, alt])) = wants {\n                let kind = if light {\n                    crate::theme::ThemeKind::Light\n                } else {\n                    crate::theme::ThemeKind::Dark\n                };\n                let mut t = Tokens::from_prefs(&self.session.prefs, kind);\n                if accent != egui::Color32::TRANSPARENT {\n                    t.app_bg = bg;\n                    t.panel_bg = panel;\n                    t.header_bg = panel;\n                    t.text = text;\n                    t.text_dim = dim;\n                    t.text_faint = dim.gamma_multiply(0.75);\n                    t.separator = sep;\n                    t.field_bg = field;\n                    t.field_border = sep;\n                    t.row = bg;\n                    t.row_alt = alt;\n                    t.row_selected = accent.gamma_multiply(0.18);\n                    t.tl_bg = bg;\n                    t.tl_ruler_bg = panel;\n                    t.switch_well = field;\n                    t.accent = accent;\n                    t.focus = accent;\n                    t.accent_hover = accent.lerp_to_gamma(egui::Color32::WHITE, 0.22);\n                    t.cti = accent;\n                    t.timecode = accent;\n                    t.hot_text = accent;\n                    t.keyframe_selected = accent;\n                }\n                self.tokens = t;\n                crate::theme::apply_visuals(&ctx, &self.tokens);\n                ctx.set_theme(crate::theme::theme_preference(\n                    &self.session.prefs.appearance.appearance_mode,\n                    self.tokens.kind.is_light(),\n                ));\n            }\n        }'


def main() -> None:
    root = Path(os.environ["EFFECTCRAFT_DIR"]).resolve()
    path = root / "crates/ui-egui/src/app/frame.rs"
    src = path.read_text(encoding="utf-8")
    if MARKER in src:
        print("palette v2 already present")
        return
    if src.count(OLD) != 1:
        raise SystemExit(f"anchor: {{src.count(OLD)}}")
    path.write_text(src.replace(OLD, NEW, 1), encoding="utf-8")
    print("palettes corrected: capcut light, blurrr/am/kuaishou dark")


if __name__ == "__main__":
    main()
